            "2. 前後を含め、筆者の論理展開を考えながら「何のことか」問いかけること。",
            "3. 言葉の重複を避けるために指示語を別の言葉に置き換えること。",
            "4. 後続の文に書かれた具体例だけを記憶すること。"
